const titles={'01':'Базовые понятия','02':'Связи между таблицами','03':'Нормализация','04':'SELECT и запросы','05':'Продвинутый SQL',setup:'Подготовка окружения',practice:'SQL-практикум'};
function route(){let key=location.hash.slice(1)||'home';if(!titles[key])key='home';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+key));document.getElementById('home').hidden=key!=='home';document.getElementById('reader').hidden=key==='home';if(key!=='home'){const url=key==='practice'?'practice.html':key==='setup'?'lectures/setup.html':'lectures/course.html#'+key;document.getElementById('frame').src=url;document.getElementById('external').href=url;document.getElementById('reader-name').textContent=titles[key];}window.scrollTo(0,0)}window.addEventListener('hashchange',route);route();
